INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 8, 'theory', 'Quiz: Docker for administrators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 0, 'What is true of a Docker container on a Linux host?', '["A separate Linux kernel runs inside", "It is a virtual machine with a lightweight hypervisor", "It is an ordinary host process in its own namespaces and control group", "It is invisible in the host''s process list"]', 2, 'Containers and the host run on one kernel. The container''s process shows up in an ordinary ps on the host, and isolation comes from namespaces, a control group, trimmed capabilities and system-call filters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 1, 'A container is started with --memory 512m --memory-swap 768m on cgroup v2. What values end up in the files?', '["memory.max 536870912, memory.swap.max 268435456", "memory.max 536870912, memory.swap.max 805306368", "memory.max 805306368, memory.swap.max 268435456", "memory.max 536870912, memory.swap.max 768"]', 0, 'The --memory-swap flag is the sum of memory and swap: 768 MiB in total. Memory is 512 MiB, so swap gets 768 minus 512, that is 256 MiB, or 268435456 bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 2, 'A mount line says lowerdir=l/AAA:l/BBB:l/CCC. Which image layer is the top one?', '["CCC: the last in the list", "BBB: the middle layer", "There is no top layer, all layers are equal", "AAA: the first in the list"]', 3, 'In lowerdir the layers are listed left to right from top to bottom: the leftmost is on top, the rightmost is the base of the image. The writable upperdir lies above them all.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 3, 'A container exited with code 137, and in docker inspect the OOMKilled flag is false. What is most likely?', '["The program ended normally with code 137", "The process was killed with SIGKILL, not because of the container''s memory limit, for example by docker stop or docker kill", "Docker could not start the command", "The container exited because of a segmentation fault"]', 1, '137 is 128 plus signal 9. Running out of memory inside the container''s limit sets OOMKilled=true; here it was most likely a kill after stop or a manual kill. If the whole host ran out of memory, check dmesg.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 8, 4, 'What does starting a container with -v /var/run/docker.sock:/var/run/docker.sock mean?', '["The container gets access only to the daemon''s log", "The container can only read the list of images", "The container controls the daemon, and so effectively has root on the host", "Nothing special: the socket is available to all containers anyway"]', 2, 'Through the socket you can start a new container with the host''s root inside. That is why access to the daemon equals root on the host, and such a container cannot be considered isolated.');
